-- Unificación de tarjetas SEM (2026-10): una acción, una tarjeta, con dónde y por qué. Generado por unificar_tarjetas_sem.py.
begin;
update seo_sem.recomendaciones r set titulo = 'Biocombustible: la separación por esquema ya está; faltan negativas en ISCC y decidir «soja epa» (75% del gasto)', detalle = 'La campaña ya tiene un grupo por esquema con su anuncio y su landing. Falta: (1) negativas para las búsquedas en inglés de quien navega el sitio de ISCC, (2) tres exactas en «ISCC EU compra» y (3) decidir la keyword «soja epa» del grupo «RFS2 compra»: se lleva el 75% del gasto con nivel de calidad 1 porque ni el anuncio ni la landing nombran la soja.', prioridad = 'alta', evidencia = '{"ficha": "campana", "unidad": "Argentina", "campana": "CU Argentina - Biocombustible - Search", "acciones": ["negativas", "keywords", "anuncio", "revisar"], "resumen": "Cerrar la separación por esquema: negativas, exactas en ISCC EU y una decisión sobre «soja epa».", "por_que": "1 sep – 20 oct 2026: 30 clics y ARS 53.620, sin conversiones. Solo gastan dos grupos. «RFS2 compra» se llevó ARS 40.393 (75%) con una sola keyword, «soja epa», que tiene nivel de calidad 1 de 10: la landing de RFS2 no menciona la soja ni «soja EPA», el anuncio tampoco, y parte de las búsquedas son de definición («que significa soja epa», ARS 2.408 por un clic). En «ISCC EU compra» (ARS 13.226) la keyword «iscc certificacion» entra en búsquedas en inglés de quien busca la base de certificados o el sitio de ISCC («iscc certificates», «iscc client section», «iscc hub», «logo iscc»): «iscc carbon» costó ARS 5.272 por un solo clic.", "ya_hecho": "La campaña ya tiene un grupo por esquema, cada uno con su anuncio y su landing: «ISCC EU compra», «ISCC sector», «ISCC plus compra», «ISCC CORSIA compra», «2BS compra» y «RFS2 compra» (estructura al 21 oct). Era lo que pedían las dos tarjetas de septiembre («Un grupo por esquema» y «Grupo nuevo con anuncio propio: ISCC»), que quedan unificadas en esta. ISCC sector, ISCC PLUS, CORSIA y 2BS todavía no tuvieron impresiones: por ahora no se tocan.", "pasos": [{"accion": "negativas", "titulo": "Cargar 9 negativas", "donde": "Toda la campaña (8) y grupo «ISCC EU compra» (1)", "detalle": "Cortan las búsquedas de quien navega el sitio de ISCC y una de definición. Las negativas de campaña que ya existen están bien.", "items": [{"accion": "agregar", "tipo": "negativa", "texto": "certificates", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«iscc certificates», «iscc all certificates», «iscc valid certificates»: buscan un certificado ajeno en la base de ISCC, no una certificadora. 4 clics, ARS 2.407."}, {"accion": "agregar", "tipo": "negativa", "texto": "iscc carbon", "concordancia": "exacta", "destino": "Toda la campaña", "motivo": "Es el nombre de la organización (International Sustainability and Carbon Certification): ARS 5.272 por un clic."}, {"accion": "agregar", "tipo": "negativa", "texto": "hub", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«iscc hub», la plataforma de ISCC para sus usuarios: ARS 1.992 por un clic."}, {"accion": "agregar", "tipo": "negativa", "texto": "client section", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "Acceso de clientes del sitio de ISCC: navegación, no compra."}, {"accion": "agregar", "tipo": "negativa", "texto": "logo", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«logo iscc», «iscc logo»: buscan la imagen del sello."}, {"accion": "agregar", "tipo": "negativa", "texto": "material list", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "Lista de materiales que publica ISCC («iscc material list 2026»)."}, {"accion": "agregar", "tipo": "negativa", "texto": "list of materials", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "La misma lista, escrita de otra forma."}, {"accion": "agregar", "tipo": "negativa", "texto": "que significa", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«que significa soja epa» costó ARS 2.408. La campaña ya bloquea «significado» y «que es», pero no «que significa»."}, {"accion": "agregar", "tipo": "negativa", "texto": "plus", "concordancia": "amplia", "destino": "Grupo «ISCC EU compra»", "motivo": "Para que las búsquedas de ISCC PLUS vayan al grupo «ISCC plus compra», que tiene su anuncio y su landing, y no a ISCC EU."}]}, {"accion": "keywords", "titulo": "Sumar tres exactas en «ISCC EU compra»", "donde": "Grupo «ISCC EU compra»", "detalle": "Sin pausar la frase «iscc certificacion»: con las negativas del paso 1 deja de traer las búsquedas en inglés.", "items": [{"accion": "agregar", "tipo": "keyword", "texto": "certificacion iscc", "concordancia": "exacta", "destino": "Grupo «ISCC EU compra»", "motivo": "Es la búsqueda principal en castellano. En exacta se paga solo eso; hoy entra por la frase «iscc certificacion», que también trae búsquedas en inglés."}, {"accion": "agregar", "tipo": "keyword", "texto": "certificado iscc", "concordancia": "exacta", "destino": "Grupo «ISCC EU compra»", "motivo": "1 clic a ARS 228 en el período y 31 impresiones orgánicas en posición 4,8: hay demanda real y barata."}, {"accion": "agregar", "tipo": "keyword", "texto": "iscc eu", "concordancia": "exacta", "destino": "Grupo «ISCC EU compra»", "motivo": "9 impresiones sin clic, entrando por otra keyword. En exacta y con el anuncio de ISCC EU gana relevancia."}]}, {"accion": "revisar", "titulo": "Decidir la keyword «soja epa»", "donde": "Grupo «RFS2 compra» · keyword «soja epa» (frase)", "detalle": "Confirmar con Control Union Argentina si el servicio de RFS2 incluye verificar soja EPA (soja para biodiésel a EE. UU.).\n· Si sí: cargar el ajuste de anuncio del paso 4, sumar la exacta [soja epa] y pedir que la landing de RFS2 nombre «soja EPA».\n· Si no: pausar «soja epa». Hoy se lleva el 75% del presupuesto de la campaña sin respaldo en la landing.", "items": [{"accion": "decidir", "tipo": "keyword", "texto": "soja epa", "concordancia": "frase", "destino": "Grupo «RFS2 compra»", "motivo": "Nivel de calidad 1 de 10, 15 clics y ARS 40.393: el 75% de la campaña."}, {"accion": "agregar", "tipo": "keyword", "texto": "soja epa", "concordancia": "exacta", "destino": "Grupo «RFS2 compra»", "motivo": "Si el servicio existe, la exacta controla el costo de la búsqueda más cara y deja a la frase solo las variantes.", "opcional": true}]}, {"accion": "anuncio", "titulo": "Si se confirma: ajustar el anuncio de «RFS2 compra»", "donde": "Grupo «RFS2 compra» · anuncio id 824719684499", "detalle": "Tres títulos y una descripción; el resto del anuncio queda igual.", "items": [{"accion": "reemplazar", "tipo": "titulo", "texto": "Verificación Soja EPA", "destino": "Anuncio id 824719684499 · grupo «RFS2 compra»", "reemplaza": "Renewable Fuel Standard 2", "prioritario": true, "motivo": "Repite la búsqueda que paga el 75% de la campaña: es lo que más sube la relevancia."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Soja EPA para EE. UU.", "destino": "Anuncio id 824719684499 · grupo «RFS2 compra»", "reemplaza": "Certificadora RFS2", "prioritario": true, "motivo": "Une la búsqueda con el destino del servicio, que es lo que define a quien compra."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Verificamos soja EPA y biodiésel para exportar a EE. UU. bajo el RFS2 de la EPA.", "destino": "Anuncio id 824719684499 · grupo «RFS2 compra»", "reemplaza": "Auditores propios en Argentina con experiencia en plantas de biodiésel y aceiteras.", "prioritario": true, "motivo": "Pone «soja EPA» en el texto largo del anuncio, con el verbo de Control Union y el destino."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Soja y biodiésel para la EPA", "destino": "Anuncio id 824719684499 · grupo «RFS2 compra»", "reemplaza": "80+ países, 274+ oficinas", "opcional": true, "motivo": "Cubre las búsquedas que mezclan soja y EPA sin nombrar RFS2."}]}], "keywords": [{"texto": "certificacion iscc", "concordancia": "exacta", "grupo": "ISCC EU compra", "accion": "agregar", "motivo": "Es la búsqueda principal en castellano. En exacta se paga solo eso; hoy entra por la frase «iscc certificacion», que también trae búsquedas en inglés."}, {"texto": "certificado iscc", "concordancia": "exacta", "grupo": "ISCC EU compra", "accion": "agregar", "motivo": "1 clic a ARS 228 en el período y 31 impresiones orgánicas en posición 4,8: hay demanda real y barata."}, {"texto": "iscc eu", "concordancia": "exacta", "grupo": "ISCC EU compra", "accion": "agregar", "motivo": "9 impresiones sin clic, entrando por otra keyword. En exacta y con el anuncio de ISCC EU gana relevancia."}, {"texto": "soja epa", "concordancia": "frase", "grupo": "RFS2 compra", "accion": "decidir (paso 3)", "motivo": "Nivel de calidad 1 de 10, 15 clics y ARS 40.393: el 75% de la campaña."}, {"texto": "soja epa", "concordancia": "exacta", "grupo": "RFS2 compra", "accion": "agregar solo si se confirma", "motivo": "Si el servicio existe, la exacta controla el costo de la búsqueda más cara y deja a la frase solo las variantes."}], "negativas": [{"texto": "certificates", "concordancia": "frase", "nivel": "campaña", "motivo": "«iscc certificates», «iscc all certificates», «iscc valid certificates»: buscan un certificado ajeno en la base de ISCC, no una certificadora. 4 clics, ARS 2.407."}, {"texto": "iscc carbon", "concordancia": "exacta", "nivel": "campaña", "motivo": "Es el nombre de la organización (International Sustainability and Carbon Certification): ARS 5.272 por un clic."}, {"texto": "hub", "concordancia": "frase", "nivel": "campaña", "motivo": "«iscc hub», la plataforma de ISCC para sus usuarios: ARS 1.992 por un clic."}, {"texto": "client section", "concordancia": "frase", "nivel": "campaña", "motivo": "Acceso de clientes del sitio de ISCC: navegación, no compra."}, {"texto": "logo", "concordancia": "frase", "nivel": "campaña", "motivo": "«logo iscc», «iscc logo»: buscan la imagen del sello."}, {"texto": "material list", "concordancia": "frase", "nivel": "campaña", "motivo": "Lista de materiales que publica ISCC («iscc material list 2026»)."}, {"texto": "list of materials", "concordancia": "frase", "nivel": "campaña", "motivo": "La misma lista, escrita de otra forma."}, {"texto": "que significa", "concordancia": "frase", "nivel": "campaña", "motivo": "«que significa soja epa» costó ARS 2.408. La campaña ya bloquea «significado» y «que es», pero no «que significa»."}, {"texto": "plus", "concordancia": "amplia", "nivel": "grupo", "grupo": "ISCC EU compra", "motivo": "Para que las búsquedas de ISCC PLUS vayan al grupo «ISCC plus compra», que tiene su anuncio y su landing, y no a ISCC EU."}], "negativas_decision": "Sí hay que ajustar negativas: 9 nuevas (8 de campaña y 1 de grupo). Las de campaña que ya existen (gratis, curso, consultoría, «que es», precio del biodiésel…) están bien y no se tocan.", "anuncios": [{"grupo": "RFS2 compra", "anuncio_id": "824719684499", "anuncio_desc": "fuerza Promedio, único anuncio del grupo, 15 clics y ARS 40.393 del 1 sep – 20 oct 2026", "accion": "Ajustar si se confirma el servicio", "motivo": "La keyword que más gasta es «soja epa» y ni el anuncio ni la landing la nombran: por eso Google le da nivel de calidad 1 y cada clic sale más caro. Nombrarla en títulos y en una descripción es lo que más sube la relevancia. Solo si Control Union verifica soja EPA.", "url": "https://argentina.controlunion.com/programa-de-certificacion/rfs2-renewable-fuel-standard-2/", "gasto_ars": 40393, "clics": 15, "ventanas": "1 sep – 20 oct 2026", "titulos_hoy": ["Certificación RFS2", "RFS2 para exportar a EE. UU.", "Verificación RFS2 y RIN", "Renewable Fuel Standard 2", "Biodiésel al mercado de EE.UU.", "Auditoría RFS2 en Argentina", "Certificadora RFS2", "Trazabilidad para la EPA", "Control Union Argentina", "Organismo de certificación", "Solicitá una cotización", "Hablá con un auditor", "Auditores en Argentina", "100+ años certificando", "80+ países, 274+ oficinas"], "descripciones_hoy": ["Verificamos el cumplimiento de RFS2 para exportar biodiésel y materias primas a EE. UU.", "Auditoría de trazabilidad y balance de masa para generar RIN bajo el programa de la EPA.", "Auditores propios en Argentina con experiencia en plantas de biodiésel y aceiteras.", "Organismo de certificación con más de 100 años y auditores propios en Argentina."], "quitar": [{"texto": "Renewable Fuel Standard 2", "motivo": "Repite «RFS2», que ya está en otros cuatro títulos."}, {"texto": "Certificadora RFS2", "motivo": "Casi igual a «Certificación RFS2»: Google no puede combinarlos."}, {"texto": "80+ países, 274+ oficinas", "motivo": "Respaldo genérico; ya está «100+ años certificando»."}, {"texto": "Auditores propios en Argentina con experiencia en plantas de biodiésel y aceiteras.", "motivo": "Repite el título «Auditores en Argentina» y la cuarta descripción («auditores propios en Argentina»)."}], "titulos_propuestos": [{"texto": "Verificación Soja EPA", "motivo": "Repite la búsqueda que paga el 75% de la campaña: es lo que más sube la relevancia.", "prioritario": true, "reemplaza": "Renewable Fuel Standard 2"}, {"texto": "Soja EPA para EE. UU.", "motivo": "Une la búsqueda con el destino del servicio, que es lo que define a quien compra.", "prioritario": true, "reemplaza": "Certificadora RFS2"}, {"texto": "Soja y biodiésel para la EPA", "motivo": "Cubre las búsquedas que mezclan soja y EPA sin nombrar RFS2.", "reemplaza": "80+ países, 274+ oficinas"}], "descripciones_propuestas": [{"texto": "Verificamos soja EPA y biodiésel para exportar a EE. UU. bajo el RFS2 de la EPA.", "motivo": "Pone «soja EPA» en el texto largo del anuncio, con el verbo de Control Union y el destino.", "prioritario": true, "reemplaza": "Auditores propios en Argentina con experiencia en plantas de biodiésel y aceiteras."}], "terminos": [{"termino": "soja epa", "relacion": "nula", "coste": 6756, "clics": 3}, {"termino": "soja epa requisitos", "relacion": "nula", "coste": 4220, "clics": 1}, {"termino": "que significa soja epa", "relacion": "nula", "coste": 2408, "clics": 1}, {"termino": "soja epa eudr", "relacion": "nula", "coste": 0, "clics": 0}, {"termino": "soja sustentable epa", "relacion": "nula", "coste": 0, "clics": 0}], "nota": "Si el servicio no incluye soja EPA, no cargar estos textos: pausar la keyword (paso 3). Los términos visibles suman ARS 13.384; el resto de los ARS 40.393 Google lo agrupa como «otros términos»."}], "organico": [{"query": "iscc", "impr": 1934, "pos": 6.8}, {"query": "iscc plus", "impr": 136, "pos": 3.3}, {"query": "certificacion iscc", "impr": 62, "pos": 5.0}, {"query": "certificación iscc", "impr": 38, "pos": 6.5}, {"query": "iscc eu", "impr": 34, "pos": 3.1}, {"query": "certificado iscc", "impr": 31, "pos": 4.8}, {"query": "norma iscc", "impr": 23, "pos": 4.8}, {"query": "iscc que es", "impr": 21, "pos": 5.3}], "organico_desde": "Argentina", "organico_hasta": "14 sep 2026", "datos_hasta": "21 oct 2026", "unifica": ["CU:SEM:anuncio:cu-argentina-biocombustible:iscc", "CU:SEM:plan:argentina:biocombustible-keywords-iscc-anuncio-2bsvs"], "revisiones": [{"mes": "2026-10", "accion": "unificación", "datos_hasta": "21 oct 2026"}]}'::jsonb, campana_id = c.id, grupo_id = g.id, actualizada_por = 'Unificación de tarjetas (Claude)'
from seo_sem.campanas c left join seo_sem.grupos g on g.campana_id = c.id and g.nombre = 'ISCC EU compra'
