with r as (update seo_sem.recomendaciones set estado = 'descartada', motivo_descarte = 'Unificada en «Biocombustible: la separación por esquema ya está; faltan negativas en ISCC y decidir «soja epa» (75% del gasto)»: una acción, una tarjeta.', mes_cierre = '2026-10', actualizada_por = 'Unificación de tarjetas (Claude)' where clave = 'CU:SEM:plan:argentina:biocombustible-keywords-iscc-anuncio-2bsvs' and estado <> 'descartada' returning id, (select estado from seo_sem.recomendaciones x where x.clave = 'CU:SEM:plan:argentina:biocombustible-keywords-iscc-anuncio-2bsvs') as antes)
insert into seo_sem.recomendacion_eventos (recomendacion_id, de_estado, a_estado, motivo, usuario) select id, antes, 'descartada', 'Unificada en «Biocombustible: la separación por esquema ya está; faltan negativas en ISCC y decidir «soja epa» (75% del gasto)»: una acción, una tarjeta.', 'Unificación de tarjetas (Claude)' from r;
update seo_sem.recomendaciones r set titulo = 'EUDR proceso: que el anuncio ofrezca la verificación y no explique el reglamento (98 clics, ARS 114.313, 0 conversiones)', detalle = 'Los dos anuncios del grupo «EUDR proceso» atraen a quien quiere aprender el reglamento: los títulos con más clics son «EUDR paso a paso», «Cómo cumplir EUDR» y «Qué exige EUDR», y la descripción más clickeada dice «Te explicamos…», tono de consultora. Además prometen una «Certificación EUDR» y un «Organismo acreditado» que no existen: EUDR se verifica. Reescribir el anuncio débil, corregir el otro y cerrar la búsqueda suelta «eudr» en este grupo.', prioridad = 'alta', evidencia = '{"ficha": "campana", "unidad": "Argentina", "campana": "CU Argentina - Agroexportación - Search", "acciones": ["anuncio", "keywords", "negativas"], "resumen": "Pasar el grupo de «te explicamos EUDR» a «verificamos tu cadena EUDR».", "por_que": "1 sep – 20 oct 2026: el grupo «EUDR proceso» llevó 98 clics y ARS 114.313 sin ninguna conversión. Los títulos que más clics traen responden a quien quiere aprender («EUDR paso a paso» 55, «Cómo cumplir EUDR» 45, «Reglamento 2023/1115» 38, «Qué exige EUDR» 37) y la descripción con más clics promete explicar («Te explicamos qué documentación…», 61): es el tono de una consultora, que Control Union no usa, y atrae estudiantes, despachantes y curiosos. Un tercio del gasto entra por la búsqueda suelta «eudr» (18 clics, ARS 35.656) a través de la keyword «reglamento deforestacion union europea». Y tres títulos prometen algo que no existe: «Certificación EUDR», «Certificación de origen» y «Organismo acreditado». EUDR no tiene certificación ni acreditación; lo que hace Control Union es verificar la debida diligencia, y la landing no menciona ninguna acreditación.", "ya_hecho": "La negativa «que significa» ya está en el grupo y en la campaña, junto con «que es», «resumen» y «definicion» (era la tarjeta «Negativos de definición», hecha). El anuncio id 824719684472 ya tiene «Verificación EUDR Argentina», que se propuso en septiembre y es su título con intención de compra que mejor anda (11 clics).", "pasos": [{"accion": "anuncio", "titulo": "Reescribir el anuncio débil", "donde": "Grupo «EUDR proceso» · anuncio id 824719684469 (fuerza Pobre)", "detalle": "Reemplazar los títulos y descripciones marcados. Es el de fuerza Pobre y el que menos rinde por clic: conviene rehacerlo y dejar el otro casi igual para comparar los dos durante 30 días.", "items": [{"accion": "reemplazar", "tipo": "titulo", "texto": "Verificamos tu cadena EUDR", "destino": "Anuncio id 824719684469 · grupo «EUDR proceso»", "reemplaza": "Qué exige EUDR", "prioritario": true, "motivo": "Dice lo que hace Control Union, con su verbo, y deja afuera a quien solo quiere entender el reglamento."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Verificación EUDR Argentina", "destino": "Anuncio id 824719684469 · grupo «EUDR proceso»", "reemplaza": "Certificación EUDR", "prioritario": true, "motivo": "Es el título con intención de compra que mejor anda en el otro anuncio del grupo (11 clics) y nombra el país."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Debida diligencia verificada", "destino": "Anuncio id 824719684469 · grupo «EUDR proceso»", "reemplaza": "EUDR: due diligence", "prioritario": true, "motivo": "Traduce «due diligence», que es lo que el exportador tiene que presentar, y lo convierte en el servicio."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Verificamos la debida diligencia EUDR de tu cadena: origen, geolocalización, trazabilidad.", "destino": "Anuncio id 824719684469 · grupo «EUDR proceso»", "reemplaza": "Geolocalización, evaluación de riesgo y declaración de due diligence: qué pide EUDR.", "prioritario": true, "motivo": "Enumera lo mismo que la descripción con más clics, pero como lo que verificamos."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Exportadores de soja y carne", "destino": "Anuncio id 824719684469 · grupo «EUDR proceso»", "reemplaza": "Evaluación de riesgo EUDR", "opcional": true, "motivo": "Nombra a quien compra: «eudr soja» es la keyword con más gasto de «EUDR compra»."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Geolocalización verificada", "destino": "Anuncio id 824719684469 · grupo «EUDR proceso»", "reemplaza": "Geolocalización de lotes", "opcional": true, "motivo": "Mismo tema que hoy, pero como servicio verificado y no como tarea a explicar."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "¿Exportás soja, carne o madera a la UE? Contanos qué exportás y te cotizamos.", "destino": "Anuncio id 824719684469 · grupo «EUDR proceso»", "reemplaza": "Organismo de certificación con más de 100 años y presencia en 80+ países.", "opcional": true, "motivo": "Cierra con un pedido concreto que solo hace quien va a contratar."}]}, {"accion": "anuncio", "titulo": "Corregir el otro anuncio, sin rehacerlo", "donde": "Grupo «EUDR proceso» · anuncio id 824719684472 (fuerza Promedio)", "detalle": "Solo tres cambios: sacar «Organismo acreditado» y «Certificación de origen», y cambiar la descripción «Te explicamos…». Sus títulos informativos («EUDR paso a paso», «Cómo cumplir EUDR») quedan: son el punto de comparación.", "items": [{"accion": "reemplazar", "tipo": "titulo", "texto": "Verificamos tu cadena EUDR", "destino": "Anuncio id 824719684472 · grupo «EUDR proceso»", "reemplaza": "Certificación de origen", "prioritario": true, "motivo": "El verbo de Control Union en el anuncio que más se muestra."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Verificamos que tu documentación y tus datos de origen cumplan el reglamento de la UE.", "destino": "Anuncio id 824719684472 · grupo «EUDR proceso»", "reemplaza": "Te explicamos qué documentación y qué datos de origen exige el reglamento de la UE.", "prioritario": true, "motivo": "Es la descripción con más clics del grupo (61): mantiene el tema y cambia «te explicamos» por «verificamos»."}, {"accion": "reemplazar"