update seo_sem.recomendaciones r set titulo = 'CU España - CAEs: pausar «certificado de eficiencia energetica» (57% del gasto: es el certificado de viviendas) · negativas y anuncio para sujetos obligados', detalle = 'La keyword amplia «certificado de eficiencia energetica» se llevó ARS 63.789 de ARS 112.250 (57%) con nivel de calidad 3: es el certificado energético de pisos y casas, otro producto, y trae particulares («certificado energético oviedo», «cuanto cuesta el certificado energetico de un piso»). Pausarla, sumar negativas de particulares y gestores, y completar el anuncio de fuerza Pobre con lo que compra un sujeto obligado: la verificación de actuaciones.', prioridad = 'alta', evidencia = '{"ficha": "campana", "unidad": "España", "campana": "CU España - CAEs - Search", "acciones": ["pausa", "negativas", "anuncio"], "resumen": "Dejar de pagar el certificado energético de viviendas y hablarle al sujeto obligado.", "por_que": "1 sep – 20 oct 2026: 110 clics y ARS 112.250, sin conversiones. El 57% (ARS 63.789, 73 clics) entra por la amplia «certificado de eficiencia energetica», nivel de calidad 3: el certificado de eficiencia energética es el que necesita un particular para vender o alquilar su vivienda, no el Certificado de Ahorro Energético (CAE) que verifica Control Union. Sus términos lo confirman: «certificado energético oviedo», «certificado energético mallorca», «obtener certificado energético gratis», «cuanto cuesta el certificado energetico de un piso». Otra parte busca quien le gestione el CAE («gestión caes particulares», «gestion de caes», «gestionar cae coche electrico», «repsol cae»): Control Union verifica, no gestiona.", "ya_hecho": "Ya están como negativas de campaña «vivienda», «casas» y «que es» (estructura al 21 oct), de lo que se propuso en septiembre. Algunos términos del período con esas palabras pueden ser anteriores a que se cargaran.", "pasos": [{"accion": "pausa", "titulo": "Pausar la keyword «certificado de eficiencia energetica»", "donde": "CU España - CAEs - Search › grupo «Certificados y Sistema CAE» · keyword amplia", "detalle": "Cambia lo propuesto en septiembre (pasarla a frase): en frase seguiría trayendo «certificado de eficiencia energetica vivienda». El grupo queda con sus 12 keywords de CAE.", "items": [{"accion": "pausar", "tipo": "keyword", "texto": "certificado de eficiencia energetica", "concordancia": "amplia", "destino": "Grupo «Certificados y Sistema CAE»", "motivo": "73 clics y ARS 63.789 (57% de la campaña), nivel de calidad 3. Es el certificado de viviendas, otro producto."}]}, {"accion": "negativas", "titulo": "Sumar 13 negativas de campaña", "donde": "CU España - CAEs - Search › toda la campaña", "detalle": "Particulares, gestores y descargas. Las negativas de campaña que ya existen no se tocan.", "items": [{"accion": "agregar", "tipo": "negativa", "texto": "particular", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gestión caes particulares» (ARS 3.498 por un clic): el particular no es cliente de una verificadora."}, {"accion": "agregar", "tipo": "negativa", "texto": "particulares", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "Las negativas no cubren plurales: hace falta también en plural."}, {"accion": "agregar", "tipo": "negativa", "texto": "piso", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«cuanto cuesta el certificado energetico de un piso»: certificado de vivienda."}, {"accion": "agregar", "tipo": "negativa", "texto": "gestion", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gestion de caes» (ARS 2.962): busca un gestor que tramite el CAE. Control Union verifica, no gestiona."}, {"accion": "agregar", "tipo": "negativa", "texto": "gestión", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "La misma palabra con tilde: Google la trata como otra negativa."}, {"accion": "agregar", "tipo": "negativa", "texto": "gestionar", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gestionar cae coche electrico» (ARS 2.419)."}, {"accion": "agregar", "tipo": "negativa", "texto": "repsol", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«repsol cae»: Repsol compra CAE a particulares; buscan venderle sus ahorros."}, {"accion": "agregar", "tipo": "negativa", "texto": "coche electrico", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "Ahorros de un particular por su coche: no es un sujeto obligado."}, {"accion": "agregar", "tipo": "negativa", "texto": "gratis", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«obtener certificado energético gratis»: la campaña no la tenía."}, {"accion": "agregar", "tipo": "negativa", "texto": "ce3", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«ce3 descargar» (ARS 2.889): es el programa para calcular el certificado de viviendas."}, {"accion": "agregar", "tipo": "negativa", "texto": "ce3x", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "La otra versión del mismo programa."}, {"accion": "agregar", "tipo": "negativa", "texto": "curso", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«curso de caes» (2 clics, ARS 1.943): formación."}, {"accion": "agregar", "tipo": "negativa", "texto": "que son", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«que son los caes en energia»: definición; la campaña ya bloquea «que es»."}]}, {"accion": "anuncio", "titulo": "Completar el anuncio de fuerza Pobre", "donde": "CU España - CAEs - Search › grupo «Certificados y Sistema CAE» · anuncio id 817970230928", "detalle": "Tiene 7 títulos y 2 descripciones: Google lo califica Pobre por falta de variantes. Se suman 6 títulos y 2 descripciones.", "items": [{"accion": "reemplazar", "tipo": "titulo", "texto": "Verificamos Actuaciones CAE", "destino": "Anuncio id 817970230928 · grupo «Certificados y Sistema CAE»", "reemplaza": "Rigor Técnico en Cada Proyecto", "prioritario": true, "motivo": "Es lo que compra un sujeto obligado y lo que trae el orgánico («verificacion cae», 239 impresiones)."}, {"accion": "agregar", "tipo": "titulo", "texto": "Sujetos Obligados y Delegados", "destino": "Anuncio id 817970230928 · grupo «Certificados y Sistema CAE»", "prioritario": true, "motivo": "Nombra a quien compra y deja afuera al particular."}, {"accion": "agregar", "tipo": "titulo", "texto": "Verificamos, No Gestionamos", "destino": "Anuncio id 817970230928 · grupo «Certificados y Sistema CAE»", "prioritario": true, "motivo": "Corta a quien busca un gestor («gestion de caes», «gestión caes particulares»)."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "No gestionamos ni tramitamos CAE de particulares: verificamos actuaciones de empresas.", "destino": "Anuncio id 817970230928 · grupo «Certificados y Sistema CAE»", "reemplaza": "Convierta sus ahorros energéticos en valor certificado, con soporte técnico continuo.", "prioritario": true, "motivo": "Filtra al particular antes del clic: hoy es la mayor parte del gasto sin cliente."}, {"accion": "agregar", "tipo": "descripcion", "texto": "Para sujetos obligados y delegados: verificación técnica de CAE con plazos claros.", "destino": "Anuncio id 817970230928 · grupo «Certificados y Sistema CAE»", "prioritario": true, "motivo": "Nombra a los dos clientes posibles del sistema CAE."}, {"accion": "agregar", "tipo": "titulo", "texto": "Verificador CAE Acreditado", "destino": "Anuncio id 817970230928 · grupo «Certificados y Sistema CAE»", "opcional": true, "motivo": "Repite «verificador cae» (123 impresiones orgánicas). La acreditación ENAC ya figura en el anuncio actual."}, {"accion": "agregar", "tipo": "titulo", "texto": "Verificación CAE para Empresas", "destino": "Anuncio id 817970230928 · grupo «Certificados y Sistema CAE»", "opcional": true, "motivo": "Variante con el tipo de cliente."}, {"accion": "agregar", "tipo": "titulo", "texto": "Solicita Verificación CAE", "destino": "Anuncio id 817970230928 · grupo 