update seo_sem.recomendaciones r set titulo = 'CU España - IFS: la campaña no tiene ninguna keyword de IFS · crear los grupos «IFS Food» e «ISO 22000 y FSSC 22000» y ajustar «Food Safety»', detalle = 'La campaña se llama IFS, pero sus 9 keywords son genéricas («certificación seguridad alimentaria» se lleva el 62%). Las búsquedas de IFS Food, ISO 22000 y FSSC 22000 caen en un anuncio que no las nombra y llevan a la página general de seguridad alimentaria, aunque el sitio tiene página propia de cada norma. Crear dos grupos con sus keywords, anuncio y página; dejar «Food Safety» para seguridad alimentaria y HACCP; y sumar negativas.', prioridad = 'media', evidencia = '{"ficha": "campana", "unidad": "España", "campana": "CU España - IFS - SEARCH", "acciones": ["estructura", "keywords", "negativas", "anuncio"], "resumen": "Que quien busca IFS, ISO 22000 o FSSC 22000 vea un anuncio y una página de esa norma.", "por_que": "1 sep – 20 oct 2026: 59 clics y ARS 115.441, sin conversiones. Un solo grupo, «Food Safety», con 9 keywords genéricas: «certificación seguridad alimentaria» (frase) se lleva ARS 71.537 (62%). Por ahí entran «ifs food» (109 impresiones), «iso 22000» (98), «fssc 22000» (78), «certificado ifs» (30), «auditoria ifs» (20) y «certificacion ifs» (19), que ven un anuncio de «seguridad alimentaria» y llegan a /industry/seguridad-alimentaria/. El sitio tiene página propia de cada norma, con demanda orgánica (Search Console, histórico): IFS Food (892 impresiones; 3.583 la versión en inglés), ISO 22000 (1.572) y FSSC 22000 (795). BRCGS no: 30 impresiones, va a negativo (ya decidido en el análisis de septiembre).", "ya_hecho": "Nada de lo propuesto en septiembre: la campaña sigue con las mismas 9 keywords y solo «curso» y «qué es» como negativas de definición o formación.", "pasos": [{"accion": "estructura", "titulo": "Crear el grupo «IFS Food»", "donde": "CU España - IFS - SEARCH › grupo nuevo «IFS Food»", "detalle": "Crear el grupo con URL final https://espana.controlunion.com/programa-de-certificacion/ifs-food/ y cargarle las 5 keywords y el anuncio de este paso.", "items": [{"accion": "crear", "tipo": "grupo", "texto": "IFS Food", "destino": "La campaña", "motivo": "URL final: https://espana.controlunion.com/programa-de-certificacion/ifs-food/"}, {"accion": "agregar", "tipo": "keyword", "texto": "ifs food", "concordancia": "exacta", "destino": "Grupo «IFS Food»", "motivo": "109 impresiones y 2 clics (ARS 4.987) en el período, hoy en un anuncio genérico. En orgánico es la búsqueda de IFS más frecuente (1.263 impresiones)."}, {"accion": "agregar", "tipo": "keyword", "texto": "certificado ifs", "concordancia": "exacta", "destino": "Grupo «IFS Food»", "motivo": "30 impresiones; con «certificado ifs food», 2 clics y ARS 3.172."}, {"accion": "agregar", "tipo": "keyword", "texto": "certificacion ifs", "concordancia": "exacta", "destino": "Grupo «IFS Food»", "motivo": "19 impresiones sin clic: el anuncio actual no nombra IFS."}, {"accion": "agregar", "tipo": "keyword", "texto": "auditoria ifs", "concordancia": "exacta", "destino": "Grupo «IFS Food»", "motivo": "20 impresiones sin clic."}, {"accion": "agregar", "tipo": "keyword", "texto": "certificación ifs food", "concordancia": "frase", "destino": "Grupo «IFS Food»", "motivo": "Cubre las variantes («ifs food certificación», «certificado ifs food») sin abrir a todo lo que contenga «ifs»."}, {"accion": "agregar", "tipo": "titulo", "texto": "Certificación IFS Food", "destino": "Anuncio nuevo · grupo «IFS Food»", "prioritario": true, "motivo": "Repite la búsqueda principal («ifs food», 109 impresiones)."}, {"accion": "agregar", "tipo": "titulo", "texto": "Certificado IFS Food", "destino": "Anuncio nuevo · grupo «IFS Food»", "prioritario": true, "motivo": "«certificado ifs» y «certificado ifs food»: 40 impresiones."}, {"accion": "agregar", "tipo": "titulo", "texto": "Auditores IFS en España", "destino": "Anuncio nuevo · grupo «IFS Food»", "prioritario": true, "motivo": "Une la norma co