: "Misma búsqueda de definición."}, {"texto": "cuestionario", "concordancia": "amplia", "nivel": "campaña", "motivo": "«cuestionario auditoria interna iso 22000» (ARS 1.861): material para estudiar."}, {"texto": "test", "concordancia": "amplia", "nivel": "campaña", "motivo": "«food safety test» (ARS 3.968): examen."}, {"texto": "why", "concordancia": "amplia", "nivel": "campaña", "motivo": "«why iso 22000 is important»: lectura, en inglés."}, {"texto": "ifs", "concordancia": "amplia", "nivel": "grupo", "grupo": "Food Safety", "motivo": "Para que las búsquedas de IFS vayan al grupo «IFS Food» y no a este."}, {"texto": "22000", "concordancia": "amplia", "nivel": "grupo", "grupo": "Food Safety", "motivo": "Para que ISO 22000 y FSSC 22000 vayan a su grupo."}, {"texto": "fssc", "concordancia": "amplia", "nivel": "grupo", "grupo": "Food Safety", "motivo": "Ídem, para «fssc» escrito sin el número."}], "negativas_decision": "Sí: 11 negativas de campaña (BRCGS, cursos de manipulación, definiciones) y 3 de grupo en «Food Safety» para que cada norma vaya a su grupo. Las que ya existen (gratis, curso, pdf, formación, qué es…) están bien.", "revisiones": [{"mes": "2026-10", "accion": "unificación", "datos_hasta": "21 oct 2026"}]}'::jsonb, campana_id = c.id, grupo_id = g.id, actualizada_por = 'Unificación de tarjetas (Claude)'
from seo_sem.campanas c left join seo_sem.grupos g on g.campana_id = c.id and g.nombre = 'Food Safety'
where r.clave = 'CU:SEM:anuncio:cu-espana-ifs:food-safety' and c.cuenta = 'actual' and c.nombre = 'CU España - IFS - SEARCH';
with r as (update seo_sem.recomendaciones set estado = 'descartada', motivo_descarte = 'Unificada en «CU España - IFS: la campaña no tiene ninguna keyword de IFS · crear los grupos «IFS Food» e «ISO 22000 y FSSC 22000» y ajustar «Food Safety»»: una acción, una tarjeta.', mes_cierre = '2026-10', actualizada_por = 'Unificación de tarjetas (Claude)' where clave = 'CU:SEM:plan:espana:ifs-genericos-y-sin-exactas' and estado <> 'descartada' returning id, (select estado from seo_sem.recomendaciones x where x.clave = 'CU:SEM:plan:espana:ifs-genericos-y-sin-exactas') as antes)
insert into seo_sem.recomendacion_eventos (recomendacion_id, de_estado, a_estado, motivo, usuario) select id, antes, 'descartada', 'Unificada en «CU España - IFS: la campaña no tiene ninguna keyword de IFS · crear los grupos «IFS Food» e «ISO 22000 y FSSC 22000» y ajustar «Food Safety»»: una acción, una tarjeta.', 'Unificación de tarjetas (Claude)' from r;
update seo_sem.recomendaciones r set titulo = 'CU España - Smeta: pausar la amplia «smeta auditoria» (85% del gasto: trae competidores y normas ISO) · negativas y ajuste del anuncio', detalle = 'La keyword amplia «smeta auditoria» se llevó ARS 102.067 de ARS 120.022 (85%) y es la puerta de los competidores (Intertek, TÜV SÜD, DNV, Veolia, OCA) y de búsquedas de ISO 9001/14001/45001. Pausarla y sumar [smeta auditoria] y [smeta] en exacta: las demás exactas de SMETA ya están. Negativas de competidores e ISO, y sacar del anuncio el «prepara tu auditoría», que es de consultora.', prioridad = 'alta', evidencia = '{"ficha": "campana", "unidad": "España", "campana": "CU España - Smeta - Search", "acciones": ["pausa", "keywords", "negativas", "anuncio"], "resumen": "Pagar solo búsquedas de SMETA, no de competidores ni de ISO.", "por_que": "1 sep – 20 oct 2026: 80 clics y ARS 120.022, sin conversiones. La amplia «smeta auditoria» (nivel de calidad 7) se llevó 67 clics y ARS 102.067 (85%). Sus términos visibles: «intertek ibérica spain s l u» (ARS 4.493), «veolia» (ARS 4.223), «tüv sud» (ARS 3.272), «dnv», «oca global», «certificaciones bureau veritas», «aenor normas iso», y una serie de búsquedas de ISO («cuadro comparativo normas iso 9001 iso 14001 y 45001», «norma iso 9001 ventajas y desventajas», «auditores iso»). También 7 clics (ARS 6.518) en «control union»: la marca propia, que se gana en orgánico sin pagar.", "ya_hecho": "La campaña ya tiene las exactas y frases de SMETA (auditoría smeta, certificación smeta, smeta 2 y 4 pilares, auditoria sedex smeta): con ellas alcanza para pausar la amplia.", "pasos": [{"accion": "pausa", "titulo": "Pausar la amplia «smeta auditoria»", "donde": "CU España - Smeta - Search › grupo «Social» · keyword amplia", "detalle": "En su lugar van las dos exactas del paso 2.", "items": [{"accion": "pausar", "tipo": "keyword", "texto": "smeta auditoria", "concordancia": "amplia", "destino": "Grupo «Social»", "motivo": "67 clics y ARS 102.067 (85% de la campaña); trae competidores y búsquedas de ISO."}]}, {"accion": "keywords", "titulo": "Sumar [smeta auditoria] y [smeta]", "donde": "CU España - Smeta - Search › grupo «Social»", "items": [{"accion": "agregar", "tipo": "keyword", "texto": "smeta auditoria", "concordancia": "exacta", "destino": "Grupo «Social»", "motivo": "Reemplaza a la amplia: se paga solo esa búsqueda."}, {"accion": "agregar", "tipo": "keyword", "texto": "smeta", "concordancia": "exacta", "destino": "Grupo «Social»", "motivo": "123 impresiones y 4 clics (ARS 4.747) en el período; en orgánico el sitio está en posición 7,8 con 1.757 impresiones."}]}, {"accion": "negativas", "titulo": "Sumar 12 negativas de campaña", "donde": "CU España - Smeta - Search › toda la campaña", "detalle": "Competidores y normas ISO. Con la amplia pausada son un seguro barato.", "items": [{"accion": "agregar", "tipo": "negativa", "texto": "intertek", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«intertek ibérica spain s l u»: ARS 4.493 por un clic. Competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "veolia", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "ARS 4.223, 2 clics."}, {"accion": "agregar", "tipo": "negativa", "texto": "tüv", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«tüv sud»: ARS 3.272 por un clic."}, {"accion": "agregar", "tipo": "negativa", "texto": "tuv", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "La misma marca escrita sin diéresis."}, {"accion": "agregar", "tipo": "negativa", "texto": "dnv", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "ARS 2.575 por un clic. Competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "oca", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«oca global»: competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "veritas", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«certificaciones bureau veritas»: 2 clics. Competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "aenor", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«aenor normas iso»: competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "isocert", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«certificaciones iso calidad isocert»: competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "iso", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "Corta de una vez las búsquedas de ISO 9001, 14001 y 45001 que entraron por la amplia («cuadro comparativo…», «auditores iso», «normas iso 2019»). Nadie busca SMETA con «iso»."}, {"accion": "agregar", "tipo": "negativa", "texto": "ohsas", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«normas iso ohsas»: 2 clics."}, {"accion": "agregar", "tipo": "negativa", "texto": "software", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«sigea software»: un programa de gestión."}]}, {"accion": "anuncio", "titulo": "Ajustar el anuncio", "donde": "CU España - Smeta - Search › grupo «Social» · anuncio id 817970221394", "items": [{"accion": "reemplazar", "tipo": "titulo", "texto": "Auditoría SMETA 4 Pilares", "destino": "Anuncio id 817970221394 · grupo «Social»", "reemplaza": "Prepara Tu Auditoría", "prioritario": true, "motivo": "«smeta 4 pilares»: nivel de calidad 7 y 101 impresiones orgánicas en posición 7,6."}, {"accion": "agregar", "tipo": "titulo", "texto": "Auditoría Social Sedex", "destino": "Anuncio id 817970221394 · grupo «Social»", "prioritario": true, "motivo": "Nombra «social» y Sedex: «auditoria social smeta» tiene nivel de calidad 3 porque el anuncio no lo dice."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Cuéntanos tu planta y tu cliente y coordinamos la auditoría SMETA en fecha.", "destino": "Anuncio id 817970221394 · grupo «Social»", "reemplaza": "Contacta con Control Union y prepara tu auditoría SMETA con soporte local.", "prioritario": true, "motivo": "Mismo cierre sin «prepara»: pide lo que necesita el auditor."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Solicita Tu Auditoría SMETA", "destino": "Anuncio id 817970221394 · grupo «Social»", "reemplaza": "Solicita Información", "opcional": true, "motivo": "Llamado a la acción con el servicio."}, {"accion": "agregar", "tipo": "titulo", "texto": "Auditores SMETA en España", "destino": "Anuncio id 817970221394 · grupo «Social»", "opcional": true, "motivo": "Equipo local."}, {"accion": "agregar", "tipo": "titulo", "texto": "Auditoría Ética y Laboral", "destino": "Anuncio id 817970221394 · grupo «Social»", "opcional": true, "motivo": "Lo que se audita, en palabras del cliente."}]}], "anuncios": [{"grupo": "Social", "anuncio_id": "817970221394", "anuncio_desc": "fuerza Promedio, 80 clics y ARS 120.022 del 1 sep – 20 oct 2026", "url": "https://espana.controlunion.com/programa-de-certificacion/smeta/", "gasto_ars": 120022, "clics": 80, "ventanas": "1 sep – 20 oct 2026", "titulos_hoy": ["Certificación SMETA", "Auditoría SMETA", "SMETA 2 Y 4 Pilares", "SEDEX Y SMETA", "SMETA España", "Solicita Información", "Prepara Tu Auditoría"], "descripciones_hoy": ["Auditorías SMETA 2 y 4 pilares para proveedores y cadenas de suministro.", "Evalúa prácticas laborales, ambientales y éticas con un equipo experto.", "Contacta con Control Union y prepara tu auditoría SMETA con soporte local.", "Habla con Control Union para definir alcance, tiempos y próximos pasos."], "accion": "Ajustar", "motivo": "El anuncio está bien en general (el problema era la keyword). Dos textos dicen «prepara tu auditoría»: preparar es lo que hace una consultora, no un organismo que audita. Y no dice «social» ni «4 pilares», que son las búsquedas con mejor nivel de calidad.", "quitar": [{"texto": "Prepara Tu Auditoría", "motivo": "Preparar la auditoría es de consultora: Control Union audita."}, {"texto": "Solicita Información", "motivo": "Genérico."}, {"texto": "Contacta con Control Union y prepara tu auditoría SMETA con soporte local.", "motivo": "Mismo problema: «prepara» y «soporte»."}], "titulos_propuestos": [{"texto": "Auditoría SMETA 4 Pilares", "motivo": "«smeta 4 pilares»: nivel de calidad 7 y 101 impresiones orgánicas en posición 7,6.", "prioritario": true, "reemplaza": "Prepara Tu Auditoría"}, {"texto": "Auditoría Social Sedex", "motivo": "Nombra «social» y Sedex: «auditoria social smeta» tiene nivel de calidad 3 porque el anuncio no lo dice.", "prioritario": true}, {"texto": "Solicita Tu Auditoría SMETA", "motivo": "Llamado a la acción con el servicio.", "reemplaza": "Solicita Información"}, {"texto": "Auditores SMETA en España", "motivo": "Equipo local."}, {"texto": "Auditoría Ética y Laboral", "motivo": "Lo que se audita, en palabras del cliente."}], "descripciones_propuestas": [{"texto": "Cuéntanos tu planta y tu cliente y coordinamos la auditoría SMETA en fecha.", "motivo": "Mismo cierre sin «prepara»: pide lo que necesita el auditor.", "prioritario": true, "reemplaza": "Contacta con Control Union y prepara tu auditoría SMETA con soporte local."}], "terminos": [{"termino": "control union", "relacion": "parcial", "coste": 6518, "clics": 7}, {"termino": "smeta", "relacion": "fuerte", "coste": 4747, "clics": 4}, {"termino": "intertek ibérica spain s l u", "relacion": "nula", "coste": 4493, "clics": 1}, {"termino": "veolia", "relacion": "nula", "coste": 4223, "clics": 2}, {"termino": "tüv sud", "relacion": "nula", "coste": 3272, "clics": 1}, {"termino": "auditoria smeta", "relacion": "fuerte", "coste": 3085, "clics": 1}, {"termino": "dnv", "relacion": "nula", "coste": 2575, "clics": 1}, {"termino": "cuadro comparativo normas iso 9001 iso 14001 y 45001", "relacion": "nula", "coste": 2567, "clics": 1}]}], "organico": [{"query": "smeta", "impr": 1757, "pos": 7.8}, {"query": "smeta certified", "impr": 199, "pos": 28.6}, {"query": "auditoria smeta", "impr": 172, "pos": 10.0}, {"query": "smeta auditoria", "impr": 105, "pos": 8.3}, {"query": "smeta 4 pilares", "impr": 101, "pos": 7.6}, {"query": "certificacion smeta", "impr": 86, "pos": 10.0}, {"query": "smeta audit", "impr": 56, "pos": 9.7}, {"query": "eti smeta", "impr": 53, "pos": 13.0}], "organico_desde": "España", "organico_hasta": "14 sep 2026", "datos_hasta": "21 oct 2026", "unifica": ["CU:SEM:anuncio:cu-espana-smeta:social", "CU:SEM:plan:espana:smeta-compra-nombres-de-competidores"], "keywords": [{"texto": "smeta auditoria", "concordancia": "amplia", "grupo": "Social", "accion": "pausar", "motivo": "67 clics y ARS 102.067 (85% de la campaña); trae competidores y búsquedas de ISO."}, {"texto": "smeta auditoria", "concordancia": "exacta", "grupo": "Social", "accion": "agregar", "motivo": "Reemplaza a la amplia: se paga solo esa búsqueda."}, {"texto": "smeta", "concordancia": "exacta", "grupo": "Social", "accion": "agregar", "motivo": "123 impresiones y 4 clics (ARS 4.747) en el período; en orgánico el sitio está en posición 7,8 con 1.757 impresiones."}], "negativas": [{"texto": "intertek", "concordancia": "amplia", "nivel": "campaña", "motivo": "«intertek ibérica spain s l u»: ARS 4.493 por un clic. Competidor."}, {"texto": "veolia", "concordancia": "amplia", "nivel": "campaña", "motivo": "ARS 4.223, 2 clics."}, {"texto": "tüv", "concordancia": "amplia", "nivel": "campaña", "motivo": "«tüv sud»: ARS 3.272 por un clic."}, {"texto": "tuv", "concordancia": "amplia", "nivel": "campaña", "motivo": "La misma marca escrita sin diéresis."}, {"texto": "dnv", "concordancia": "amplia", "nivel": "campaña", "motivo": "ARS 2.575 por un clic. Competidor."}, {"texto": "oca", "concordancia": "amplia", "nivel": "campaña", "motivo": "«oca global»: competidor."}, {"texto": "veritas", "concordancia": "amplia", "nivel": "campaña", "motivo": "«certificaciones bureau veritas»: 2 clics. Competidor."}, {"texto": "aenor", "concordancia": "amplia", "nivel": "campaña", "motivo": "«aenor normas iso»: competidor."}, {"texto": "isocert", "concordancia": "amplia", "nivel": "campaña", "motivo": "«certificaciones iso calidad isocert»: competidor."}, {"texto": "iso", "concordancia": "amplia", "nivel": "campaña", "motivo": "Corta de una vez las búsquedas de ISO 9001, 14001 y 45001 que entraron por la amplia («cuadro comparativo…», «auditores iso», «normas iso 2019»). Nadie busca SMETA con «iso»."}, {"texto": "ohsas", "concordancia": "amplia", "nivel": "campaña", "motivo": "«normas iso ohsas»: 2 clics."}, {"texto": "software", "concordancia": "amplia", "nivel": "campaña", "motivo": "«sigea software»: un programa de gestión."}], "negativas_decision": "Sí: 12 negativas de campaña. Con la amplia pausada casi no deberían hacer falta, pero cuestan nada y cubren las variantes que pueda traer la frase. No se negativiza «control union»: con la amplia pausada deja de pagarse sola.", "revisiones": [{"mes": "2026-10", "accion": "unificación", "datos_hasta": "21 oct 2026"}]}'::jsonb, campana_id = c.id, grupo_id = g.id, actualizada_por = 'Unificación de tarjetas (Claude)'
