update seo_sem.recomendaciones r set titulo = 'CU Portugal - Plásticos: pausar las dos amplias de UNE 15343 (97% del gasto del grupo, fuera de tema) · negativas y corregir los dos anuncios', detalle = 'En el grupo «UNE 15343», las amplias «une 15343» y «norma 15343» se llevaron ARS 64.310 de ARS 66.380 (97%) con búsquedas de economía circular, PPWR, ODS y consultoras. Pausarlas (las exactas y frases de la norma ya están), sumar negativas, y corregir los dos anuncios: textos de consultoría («apoia», «orientação») y un título en castellano en el anuncio de RecyClass.', prioridad = 'media', evidencia = '{"ficha": "campana", "unidad": "Portugal", "campana": "CU Portugal - Plasticos - Search", "acciones": ["pausa", "keywords", "negativas", "anuncio"], "resumen": "Que el grupo de UNE 15343 pague solo búsquedas de la norma, y anuncios con el vocabulario de una certificadora.", "por_que": "1 sep – 20 oct 2026: el grupo «UNE 15343» llevó 20 clics y ARS 66.380. «une 15343» (amplia) se llevó ARS 43.876 y «norma 15343» (amplia) ARS 20.434: el 97%. De sus términos con clic, uno solo es de la norma («une en 15343», ARS 2.070); el resto son «ods pt», «regulamento 2025 40», «bso consulting», «ppwr webinar», «epd», «como reduzir a produção de resíduos». En orgánico el sitio está 3º para «en 15343». En «RecyClass» la exacta y la frase ya existen (20 clics, ARS 41.573) y el sitio también rankea 3º.", "ya_hecho": "«recyclass» ya está en exacta, como se propuso en septiembre. Faltaba el tope: queda como revisión (paso 5).", "pasos": [{"accion": "pausa", "titulo": "Pausar las amplias «une 15343» y «norma 15343»", "donde": "CU Portugal - Plasticos - Search › grupo «UNE 15343»", "detalle": "El grupo queda con sus 12 exactas y frases de la norma.", "items": [{"accion": "pausar", "tipo": "keyword", "texto": "une 15343", "concordancia": "amplia", "destino": "Grupo «UNE 15343»", "motivo": "13 clics y ARS 43.876 (66% del grupo), casi todo fuera de tema."}, {"accion": "pausar", "tipo": "keyword", "texto": "norma 15343", "concordancia": "amplia", "destino": "Grupo «UNE 15343»", "motivo": "6 clics y ARS 20.434 (31%): «bso consulting», «ods pt», «como reduzir a produção de resíduos»."}]}, {"accion": "keywords", "titulo": "Sumar la frase «en 15343»", "donde": "CU Portugal - Plasticos - Search › grupo «UNE 15343»", "items": [{"accion": "agregar", "tipo": "keyword", "texto": "en 15343", "concordancia": "frase", "destino": "Grupo «UNE 15343»", "motivo": "Así la cita la gente, con o sin año («une en 15343 2008», «une-en 15343:2008»). En orgánico, 45 impresiones en posición 3,2."}]}, {"accion": "negativas", "titulo": "Sumar 11 negativas de campaña", "donde": "CU Portugal - Plasticos - Search › toda la campaña", "items": [{"accion": "agregar", "tipo": "negativa", "texto": "ppwr", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«ppwr», «ppwr webinar», «ppwr regulation»: el reglamento europeo de envases, no la norma."}, {"accion": "agregar", "tipo": "negativa", "texto": "regulamento", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«regulamento 2025 40» (ARS 4.487 por un clic): el mismo reglamento."}, {"accion": "agregar", "tipo": "negativa", "texto": "ods", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«ods pt» (ARS 4.521), «ods»: Objetivos de Desarrollo Sostenible."}, {"accion": "agregar", "tipo": "negativa", "texto": "circular", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«economia circular» (65 impresiones), «ecónomia circular», «empresas de economia circular»: una sola negativa cubre las tres."}, {"accion": "agregar", "tipo": "negativa", "texto": "resíduos", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gestão de resíduos», «como reduzir a produção de resíduos» (ARS 2.767)."}, {"accion": "agregar", "tipo": "negativa", "texto": "epd", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "Declaración ambiental de producto, otro servicio (ARS 3.141)."