insert into seo_sem.recomendacion_eventos (recomendacion_id, de_estado, a_estado, motivo, usuario) select id, antes, 'descartada', 'Unificada en «CU Portugal - Plásticos: pausar las dos amplias de UNE 15343 (97% del gasto del grupo, fuera de tema) · negativas y corregir los dos anuncios»: una acción, una tarjeta.', 'Unificación de tarjetas (Claude)' from r;
update seo_sem.recomendaciones r set titulo = 'CU Portugal - Textile: cortar OEKO-TEX y el ruido de GRS · exactas de GOTS · anuncio de GOTS sin «apoio»', detalle = 'Campaña sana con dos fugas: la amplia «certificação gots portugal» trae OEKO-TEX (Control Union no lo certifica) y la amplia «global recycled standard» trae PPWR y ODS. Pausar la primera, negativas para las dos, exactas para las búsquedas de GOTS que más compran, y sacar del anuncio de GOTS el «Apoio a marcas», que es de consultora.', prioridad = 'alta', evidencia = '{"ficha": "campana", "unidad": "Portugal", "campana": "CU Portugal - Textile - Search", "acciones": ["pausa", "keywords", "negativas", "anuncio"], "resumen": "Cortar OEKO-TEX y el ruido de GRS, y hablar como certificadora.", "por_que": "1 sep – 20 oct 2026: 78 clics y ARS 117.016. «oeko tex» y «oeko tex standard 100» costaron ARS 8.762 (5 clics), casi todo por la amplia «certificação gots portugal» (6 clics, ARS 9.446): Control Union no certifica OEKO-TEX (en el análisis de España, cero apariciones en 20.561 búsquedas orgánicas). La amplia «global recycled standard» (ARS 16.494) trae «ppwr», «ods», «sdgs un», «sustainable 17 goals». La búsqueda que más clics trajo, «gots certification» (6 clics, ARS 9.043), entra por otra keyword.", "ya_hecho": "«grs portugal» ya está en exacta, como se propuso en septiembre.", "pasos": [{"accion": "pausa", "titulo": "Pausar la amplia «certificação gots portugal»", "donde": "CU Portugal - Textile - Search › grupo «GOTS»", "detalle": "Las frases y exactas de «certificação gots» cubren lo mismo sin OEKO-TEX.", "items": [{"accion": "pausar", "tipo": "keyword", "texto": "certificação gots portugal", "concordancia": "amplia", "destino": "Grupo «GOTS»", "motivo": "6 clics y ARS 9.446, casi todos en búsquedas de OEKO-TEX."}]}, {"accion": "keywords", "titulo": "Sumar 3 exactas de GOTS", "donde": "CU Portugal - Textile - Search › grupo «GOTS»", "items": [{"accion": "agregar", "tipo": "keyword", "texto": "gots certification", "concordancia": "exacta", "destino": "Grupo «GOTS»", "motivo": "La búsqueda con más clics del período (6, ARS 9.043), hoy por «global organic textile standard»."}, {"accion": "agregar", "tipo": "keyword", "texto": "gots", "concordancia": "exacta", "destino": "Grupo «GOTS»", "motivo": "156 impresiones y 4 clics (ARS 3.433). En orgánico el sitio está en posición 5,8 con 1.310 impresiones: el pago suma."}, {"accion": "agregar", "tipo": "keyword", "texto": "certificado gots", "concordancia": "exacta", "destino": "Grupo «GOTS»", "motivo": "3 clics en el período y 85 impresiones orgánicas en posición 4,5."}]}, {"accion": "negativas", "titulo": "Sumar 8 negativas de campaña", "donde": "CU Portugal - Textile - Search › toda la campaña", "detalle": "La campaña no tiene ninguna negativa propia: las de descarga y empleo están repetidas en cada grupo.", "items": [{"accion": "agregar", "tipo": "negativa", "texto": "oeko", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«oeko tex», «oeko tex standard 100»: ARS 8.762. Control Union no certifica OEKO-TEX."}, {"accion": "agregar", "tipo": "negativa", "texto": "oekotex", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "La misma marca escrita junta."}, {"accion": "agregar", "tipo": "negativa", "texto": "ppwr", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "Reglamento europeo de envases (ARS 2.951)."}, {"accion": "agregar", "tipo": "negativa", "texto": "ods", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "Objetivos de Desarrollo Sostenible (ARS 2.908)."}, {"accion": "agregar", "tipo": "negativa", "texto": "sdgs", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "Lo mismo en inglés («sdgs un», ARS 1.478)."}, {"accion": "agregar", "tipo": "negativa", "texto": "goals", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«sustainable 17 goals» (ARS 1.298)."}, {"accion": "agregar", "tipo": "negativa", "texto": "resíduos", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gestão de resíduos industriais» (ARS 1.217)."}, {"accion": "agregar", "tipo": "negativa", "texto": "database", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gots database»: busca un certificado ajeno en la base de GOTS."}]}, {"accion": "anuncio", "titulo": "Ajustar el anuncio de GOTS", "donde": "CU Portugal - Textile - Search › grupo «GOTS» · anuncio id 817970230778", "items": [{"accion": "agregar", "tipo": "titulo", "texto": "Norma GOTS: Certificamos", "destino": "Anuncio id 817970230778 · grupo «GOTS»", "prioritario": true, "motivo": "«norma gots» (2 clics) con el verbo de Control Union."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Peça a Sua Certificação GOTS", "destino": "Anuncio id 817970230778 · grupo «GOTS»", "reemplaza": "Peça Informação", "prioritario": true, "motivo": "Llamado a la acción con el servicio, no «informação»."}, {"accion": "agregar", "tipo": "titulo", "texto": "Certificado GOTS", "destino": "Anuncio id 817970230778 · grupo «GOTS»", "prioritario": true, "motivo": "«certificado gots»: 3 clics en el período."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Certificamos GOTS: têxteis orgânicos com rastreabilidade da fibra ao produto final.", "destino": "Anuncio id 817970230778 · grupo «GOTS»", "reemplaza": "Apoio a marcas, fabricantes e fornecedores têxteis em Portugal.", "prioritario": true, "motivo": "Dice qué certifica y con qué alcance."}, {"accion": "agregar", "tipo": "titulo", "texto": "Organismo de Certificação", "destino": "Anuncio id 817970230778 · grupo «GOTS»", "opcional": true, "motivo": "Dice qué es Control Union."}, {"accion": "agregar", "tipo": "titulo", "texto": "Símbolo GOTS Para a Sua Marca", "destino": "Anuncio id 817970230778 · grupo «GOTS»", "opcional": true, "motivo": "«gots symbol»: quien quiere usar el sello en su producto."}, {"accion": "agregar", "tipo": "titulo", "texto": "Certificação GOTS 8.0", "destino": "Anuncio id 817970230778 · grupo «GOTS»", "opcional": true, "motivo": "«gots 8.0» tuvo 15 impresiones. Confirmar con la unidad que ya audita sobre esa versión antes de publicarlo."}]}], "anuncios": [{"grupo": "GOTS", "anuncio_id": "817970230778", "anuncio_desc": "fuerza Promedio, 51 clics y ARS 75.251 del 1 sep – 20 oct 2026", "url": "https://portugal.controlunion.com/programas-de-certificacao/gots-global-organic-textile-standard/", "gasto_ars": 75251, "clics": 51, "ventanas": "1 sep – 20 oct 2026", "titulos_hoy": ["Certificação GOTS", "Auditoria GOTS", "Têxteis Orgânicos", "Global Organic Textile", "Cadeia Têxtil Sustentável", "GOTS Portugal", "Peça Informação"], "descripciones_hoy": ["Certificação GOTS para têxteis orgânicos e cadeias sustentáveis.", "Apoio a marcas, fabricantes e fornecedores têxteis em Portugal.", "Peça informação e conheça os requisitos da certificação têxtil.", "Fale com a Control Union para definir escopo, prazos e próximos passos."], "accion": "Ajustar", "motivo": "«Apoio a marcas, fabricantes e fornecedores» es vocabulario de consultora; Control Union certifica. Y no dice «norma» ni «certificamos», que es como busca quien compra («norma gots», «certificado gots»). Tiene 7 títulos: hay lugar para sumar.", "quitar": [{"texto": "Peça Informação", "motivo": "Genérico."}, {"texto": "Apoio a marcas, fabricantes e fornecedores têxteis em Portugal.", "motivo": "«Apoio» es de consultora."}], "titulos_propuestos": [{"texto": "Norma GOTS: Certificamos", "motivo": "«norma gots» (2 clics) con el verbo de Control Union.", "prioritario": true}, {"texto": "Peça a Sua Certificação GOTS", "motivo": "Llamado a la acción con el servicio, no «informação».", "prioritario": true, "reemplaza": "Peça Informação"}, {"texto": "Certificado GOTS", "motivo": "«certificado gots»: 3 clics en el período.", "prioritario": true}, {"texto": "Organismo de Certificação", "motivo": "Dice qué es Control Union."}, {"texto": "Símbolo GOTS Para a Sua Marca", "motivo": "«gots symbol»: quien quiere usar el sello en su producto."}, {"texto": "Certificação GOTS 8.0", "motivo": "«gots 8.0» tuvo 15 impresiones. Confirmar con la unidad que ya audita sobre esa versión antes de publicarlo."}], "descripciones_propuestas": [{"texto": "Certificamos GOTS: têxteis orgânicos com rastreabilidade da fibra ao produto final.", "motivo": "Dice qué certifica y con qué alcance.", "prioritario": true, "reemplaza": "Apoio a marcas, fabricantes e fornecedores têxteis em Portugal."}], "terminos": [{"termino": "gots certification", "relacion": "fuerte", "coste": 9043, "clics": 6}, {"termino": "oeko tex", "relacion": "nula", "coste": 7032, "clics": 4}, {"termino": "certificado gots", "relacion": "fuerte", "coste": 4698, "clics": 3}, {"termino": "global organic textile standard", "relacion": "fuerte", "coste": 4194, "clics": 4}, {"termino": "gots", "relacion": "fuerte", "coste": 3433, "clics": 4}, {"termino": "certificação gots", "relacion": "fuerte", "coste": 2612, "clics": 2}, {"termino": "gots symbol", "relacion": "parcial", "coste": 2330, "clics": 1}, {"termino": "norma gots", "relacion": "fuerte", "coste": 2057, "clics": 2}]}], "organico": [{"query": "gots", "impr": 1310, "pos": 5.8}, {"query": "certificação gots", "impr": 120, "pos": 3.6}, {"query": "global recycled standard", "impr": 101, "pos": 5.1}, {"query": "certificado gots", "impr": 85, "pos": 4.5}, {"query": "gots certification", "impr": 41, "pos": 7.3}, {"query": "global sustainable tourism council", "impr": 29, "pos": 7.5}, {"query": "global organic textile standard", "impr": 29, "pos": 6.0}, {"query": "global recycled standard (grs)", "impr": 20, "pos": 4.7}], "organico_desde": "Portugal", "organico_hasta": "14 sep 2026", "datos_hasta": "21 oct 2026", "unifica": ["CU:SEM:anuncio:cu-portugal-textile:gots", "CU:SEM:plan:portugal:textile-bien-con-ruido-nuevo"], "keywords": [{"texto": "certificação gots portugal", "concordancia": "amplia", "grupo": "GOTS", "accion": "pausar", "motivo": "6 clics y ARS 9.446, casi todos en búsquedas de OEKO-TEX."}, {"texto": "gots certification", "concordancia": "exacta", "grupo": "GOTS", "accion": "agregar", "motivo": "La búsqueda con más clics del período (6, ARS 9.043), hoy por «global organic textile standard»."}, {"texto": "gots", "concordancia": "exacta", "grupo": "GOTS", "accion": "agregar", "motivo": "156 impresiones y 4 clics (ARS 3.433). En orgánico el sitio está en posición 5,8 con 1.310 impresiones: el pago suma."}, {"texto": "certificado gots", "concordancia": "exacta", "grupo": "GOTS", "accion": "agregar", "motivo": "3 clics en el período y 85 impresiones orgánicas en posición 4,5."}], "negativas": [{"texto": "oeko", "concordancia": "amplia", "nivel": "campaña", "motivo": "«oeko tex», «oeko tex standard 100»: ARS 8.762. Control Union no certifica OEKO-TEX."}, {"texto": "oekotex", "concordancia": "amplia", "nivel": "campaña", "motivo": "La misma marca escrita junta."}, {"texto": "ppwr", "concordancia": "amplia", "nivel": "campaña", "motivo": "Reglamento europeo de envases (ARS 2.951)."}, {"texto": "ods", "concordancia": "amplia", "nivel": "campaña", "motivo": "Objetivos de Desarrollo Sostenible (ARS 2.908)."}, {"texto": "sdgs", "concordancia": "amplia", "nivel": "campaña", "motivo": "Lo mismo en inglés («sdgs un», ARS 1.478)."}, {"texto": "goals", "concordancia": "amplia", "nivel": "campaña", "motivo": "«sustainable 17 goals» (ARS 1.298)."}, {"texto": "resíduos", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gestão de resíduos industriais» (ARS 1.217)."}, {"texto": "database", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gots database»: busca un certificado ajeno en la base de GOTS."}], "negativas_decision": "Sí: 8 negativas de campaña. Corrige la tarjeta de septiembre en un punto: «wordly» no va a negativo todavía. Higg pasó a llamarse Worldly (a confirmar), así que «wordly fem» (1 clic, ARS 2.929) puede ser la misma búsqueda que «higg fem». Si en 30 días no trae contactos, negativizar.", "revisiones": [{"mes": "2026-10", "accion": "unificación", "datos_hasta": "21 oct 2026"}]}'::jsonb, campana_id = c.id, grupo_id = g.id, actualizada_por = 'Unificación de tarjetas (Claude)'
