update seo_sem.recomendaciones r set titulo = 'CU USA - Organic USDA NOP: negativas de definición y competidores (41% de los términos visibles) · que el anuncio diga «Control Union»', detalle = 'Es la campaña más cara (ARS 552.452 en el período, cero conversiones). De los términos visibles, el 41% son definiciones («what does certified organic mean»), competidores (QCS, OneCert, QAI), quien quiere ser certificador y la base de datos del USDA. Negativas de campaña y un anuncio que use «Control Union», que es lo que la gente busca, en lugar de «CUC USA».', prioridad = 'alta', evidencia = '{"ficha": "campana", "unidad": "Estados Unidos", "campana": "CU United States - Organic - USDA NOP - Search", "acciones": ["negativas", "anuncio", "revisar"], "resumen": "Dejar de pagar definiciones y competidores en la campaña más cara.", "por_que": "1 sep – 20 oct 2026: ARS 552.452 y 63 clics (ARS 8.769 por clic), sin conversiones. De ARS 265.887 en términos visibles, ARS 109.862 (41%) son: definiciones («what does certified organic mean» ARS 18.726, «what is certified organic» ARS 8.733), competidores («qcs organic» ARS 17.523, «one cert organic» ARS 14.832, «qai certified organic» ARS 6.715), quien quiere ser certificador («how to become an organic certifier» ARS 11.087), la formación del USDA («organic integrity learning center» ARS 15.818) y una empresa («mister specialties llc» ARS 16.429). La keyword exacta «organic certification» (nivel de calidad 3) se lleva ARS 136.588, el 25% de la campaña.", "ya_hecho": "Ninguna de las negativas propuestas en septiembre está cargada.", "pasos": [{"accion": "negativas", "titulo": "Sumar 11 negativas de campaña", "donde": "CU United States - Organic - USDA NOP - Search › toda la campaña", "detalle": "Las 54 que ya tiene (portal, cosmetics, jobs, gots…) están bien.", "items": [{"accion": "agregar", "tipo": "negativa", "texto": "what does", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«what does certified organic mean»: ARS 18.726 por 2 clics."}, {"accion": "agregar", "tipo": "negativa", "texto": "what is", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«what is certified organic»: ARS 8.733 por un clic."}, {"accion": "agregar", "tipo": "negativa", "texto": "meaning", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "Definiciones."}, {"accion": "agregar", "tipo": "negativa", "texto": "mean", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "Definiciones."}, {"accion": "agregar", "tipo": "negativa", "texto": "become an organic certifier", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«how to become an organic certifier» (ARS 11.087): quiere trabajar de certificador."}, {"accion": "agregar", "tipo": "negativa", "texto": "qcs", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«qcs organic» (ARS 17.523): Quality Certification Services, competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "one cert", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«one cert organic» (ARS 14.832): competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "onecert", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "El mismo competidor escrito junto."}, {"accion": "agregar", "tipo": "negativa", "texto": "qai", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«qai certified organic» (ARS 6.715): competidor."}, {"accion": "agregar", "tipo": "negativa", "texto": "learning center", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«organic integrity learning center» (ARS 15.818): la capacitación del USDA."}, {"accion": "agregar", "tipo": "negativa", "texto": "mister specialties", "concordancia": "frase", "destino": "Toda la campaña", "motivo": "«mister specialties llc» (ARS 16.429): una empresa puntual."}]}, {"accion": "anuncio", "titulo": "Cambiar 4 títulos y 1 descripción", "donde": "CU United States - Organic - USDA NOP - Search › grupo «Switch & Get Certified» · anuncio id 821810301980", "detalle": "El anuncio ya tiene los 15 títulos que permite Google: cada título nuevo reemplaza a uno.", "items": [{"accion": "reemplazar", "tipo": "titulo", "texto": "Control Union USA", "destino": "Anuncio id 821810301980 · grupo «Switch & Get Certified»", "reemplaza": "Organic Cert by CUC USA", "prioritario": true, "motivo": "Es la marca que la gente escribe («control union organic certification», ARS 15.281)."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "How to Get Certified Organic", "destino": "Anuncio id 821810301980 · grupo «Switch & Get Certified»", "reemplaza": "Organic Cert, Simplified", "prioritario": true, "motivo": "Repite tres búsquedas de productores que quieren certificarse (unos ARS 25.000 en el período)."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "USDA NOP-accredited organic certifier for farms, handlers and processors in the U.S.", "destino": "Anuncio id 821810301980 · grupo «Switch & Get Certified»", "reemplaza": "CUC USA: USDA NOP Approved-organic certification for U.S. businesses.", "prioritario": true, "motivo": "Corrige el error y nombra para quién es. Confirmar el alcance con la unidad."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "NOP-Accredited Certifier", "destino": "Anuncio id 821810301980 · grupo «Switch & Get Certified»", "reemplaza": "CUC USA: 80+ Countries", "opcional": true, "motivo": "Nombra el programa (NOP), que también se busca («nop certificate»)."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Organic Certification: Farms", "destino": "Anuncio id 821810301980 · grupo «Switch & Get Certified»", "reemplaza": "Named Contact, Every Time", "opcional": true, "motivo": "Nombra el alcance. Confirmar con la unidad."}]}, {"accion": "revisar", "titulo": "Decidir «organic chicken certification» con la unidad", "donde": "CU United States - Organic - USDA NOP - Search › grupo «Switch & Get Certified»", "detalle": "Costó ARS 11.056 en septiembre. Si el alcance de CU USA incluye ganadería (livestock), queda; si no, va a negativo.", "items": [{"accion": "decidir", "tipo": "texto", "texto": "¿CU USA certifica ganadería orgánica (livestock)?", "destino": "Consulta a CU USA"}, {"accion": "agregar", "tipo": "negativa", "texto": "organic chicken", "concordancia": "frase", "destino": "Toda la campaña", "opcional": true, "motivo": "Solo si la respuesta es no: «organic chicken certification» costó ARS 11.056 por un clic en septiembre."}]}, {"accion": "revisar", "titulo": "Poner un tope de CPC", "donde": "CU United States - Organic - USDA NOP - Search › configuración de la campaña › estrategia «Maximizar clics»", "detalle": "El clic sale ARS 8.769 en promedio, pero hubo clics sueltos de ARS 14.800 a 17.500 en competidores y búsquedas ajenas («qcs organic», «mister specialties llc», «organic integrity learning center»). Un límite de CPC máximo los evita.", "items": [{"accion": "cambiar", "tipo": "texto", "texto": "Límite de oferta de CPC máximo: ARS 12.000", "destino": "Configuración de la campaña › Ofertas › Maximizar clics", "motivo": "Deja pasar los clics que valen (promedio ARS 8.769; «organic certification», la keyword principal, ARS 10.843) y corta los de ARS 14.800–17.500."}]}], "anuncios": [{"grupo": "Switch & Get Certified", "anuncio_id": "821810301980", "anuncio_desc": "fuerza Promedio, 50 clics y ARS 397.983 del 1 sep – 20 oct 2026", "url": "https://northamerica.controlunion.com/certification-program/usda-organic-nop-certification/", "gasto_ars": 397983, "clics": 50, "ventanas": "1 sep – 20 oct 2026", "titulos_hoy": ["CUC USA Organic Certification", "USDA Organic Certification", "Get USDA Organic Certified", "Switch Organic Certifiers", "Change Your Organic Certifier", "CUC USA: 80+ Countries", "USDA-Accredited Certifier", "No Lapse When You Switch", "Transfer Your Organic Cert", "Organic Cert by CUC USA", "Request an Organic Cert Quote", "Named Contact, Every Time", "Global Organic Certifier", "Talk to a Certification Expert", "Organic Cert, Simplified"], "descripciones_hoy": ["CUC USA: USDA NOP Approved-organic certification for U.S. businesses.", "Switch certifiers with no lapse in status. CUC USA manages the transfer.", "Global network, multi-scheme bundling, and a certifier that knows trade.", "Request a quote and talk to a U.S.-based organic certification expert."], "accion": "Ajustar", "motivo": "La gente busca «control union organic certification» (3 clics) y «certified organic by control union», pero el anuncio dice «CUC USA», que nadie busca. Además tiene títulos sin contenido («Named Contact, Every Time», «Organic Cert, Simplified») y una descripción con un error («USDA NOP Approved-organic»). Ya tiene 15 títulos, el máximo: cada uno nuevo reemplaza a uno.", "quitar": [{"texto": "Named Contact, Every Time", "motivo": "Promesa vaga, sin norma ni servicio."}, {"texto": "CUC USA: 80+ Countries", "motivo": "«CUC» no lo busca nadie, y repite «Global Organic Certifier»."}, {"texto": "Organic Cert by CUC USA", "motivo": "Repite «CUC USA Organic Certification»."}, {"texto": "Organic Cert, Simplified", "motivo": "Genérico."}, {"texto": "CUC USA: USDA NOP Approved-organic certification for U.S. businesses.", "motivo": "«Approved-organic» está mal escrito y «CUC USA» no es el nombre que se busca."}], "titulos_propuestos": [{"texto": "Control Union USA", "motivo": "Es la marca que la gente escribe («control union organic certification», ARS 15.281).", "prioritario": true, "reemplaza": "Organic Cert by CUC USA"}, {"texto": "How to Get Certified Organic", "motivo": "Repite tres búsquedas de productores que quieren certificarse (unos ARS 25.000 en el período).", "prioritario": true, "reemplaza": "Organic Cert, Simplified"}, {"texto": "NOP-Accredited Certifier", "motivo": "Nombra el programa (NOP), que también se busca («nop certificate»).", "reemplaza": "CUC USA: 80+ Countries"}, {"texto": "Organic Certification: Farms", "motivo": "Nombra el alcance. Confirmar con la unidad.", "reemplaza": "Named Contact, Every Time"}], "descripciones_propuestas": [{"texto": "USDA NOP-accredited organic certifier for farms, handlers and processors in the U.S.", "motivo": "Corrige el error y nombra para quién es. Confirmar el alcance con la unidad.", "prioritario": true, "reemplaza": "CUC USA: USDA NOP Approved-organic certification for U.S. businesses."}], "terminos": [{"termino": "organic certification", "relacion": "fuerte", "coste": 32528, "clics": 3}, {"termino": "what does certified organic mean", "relacion": "nula", "coste": 18726, "clics": 2}, {"termino": "control union organic certification", "relacion": "fuerte", "coste": 15281, "clics": 3}, {"termino": "certified organic", "relacion": "parcial", "coste": 14362, "clics": 1}, {"termino": "third party organic certifiers", "relacion": "fuerte", "coste": 11880, "clics": 1}, {"termino": "how to become an organic certifier", "relacion": "nula", "coste": 11087, "clics": 1}, {"termino": "organic certifications", "relacion": "fuerte", "coste": 10972, "clics": 1}, {"termino": "how to get organic certified", "relacion": "fuerte", "coste": 8977, "clics": 1}], "nota": "El alcance (farms, handlers, processors) es un supuesto: la campaña tiene un grupo de handlers y procesadores, pero confirmarlo con CU USA antes de publicar."}], "organico": [{"query": "control union organic certification", "impr": 40, "pos": 35.8}, {"query": "organic content standard", "impr": 32, "pos": 63.9}, {"query": "what are the best testing services for verifying organic and non-gmo claims?", "impr": 4, "pos": 9.2}, {"query": "ocs organic", "impr": 2, "pos": 38.5}, {"query": "site:controlunion.com global organic latex standard gols official", "impr": 2, "pos": 9.0}, {"query": "site:controlunion.com gols global organic latex standard official", "impr": 2, "pos": 1.5}, {"query": "organic content standard (ocs)", "impr": 2, "pos": 49.5}, {"query": "certified organic by control union", "impr": 1, "pos": 1.0}], "organico_desde"