update seo_sem.recomendaciones r set titulo = 'PS Argentina - ESG: negativas para «gri + número» · títulos para CSRD y estándares GRI', detalle = 'La campaña más sana de Peterson. La frase «reporte GRI» (65% del gasto) trae 70 variantes de «gri + número» (quien lee un indicador puntual): 8 clics y ARS 9.379. Negativas para los números con clic y «ejemplos»; en el anuncio, títulos para CSRD y estándares GRI, que son las búsquedas que más se repiten.', prioridad = 'media', evidencia = '{"ficha": "campana", "unidad": "Argentina", "campana": "PS Argentina - SuSe - ESG / Reportes - Search", "acciones": ["negativas", "anuncio"], "resumen": "Dejar de pagar lectores de indicadores GRI y hablarle a quien tiene que reportar.", "por_que": "1 sep – 20 oct 2026: 74 clics y ARS 113.464. «reporte GRI» (frase, nivel de calidad 3) se lleva ARS 74.136 (65%). Por ahí entraron 70 variantes de «gri + número» («gri 404 1», «gri 204», «gri 201»…): 8 clics y ARS 9.379. Quien busca un indicador puntual está leyendo la norma, no buscando quién le haga el reporte. Lo que sí se repite y el anuncio no nombra: «csrd» (76 impresiones, 2 clics), «estándares gri» (31), «indicadores gri» (15, 2 clics).", "ya_hecho": "«que es», «definicion», «ejemplo» y «plantilla» ya son negativas de campaña.", "pasos": [{"accion": "negativas", "titulo": "Sumar 8 negativas de campaña", "donde": "PS Argentina - SuSe - ESG / Reportes - Search › toda la campaña", "items": [{"accion": "agregar", "tipo": "negativa", "texto": "201", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gri 201»: indicador puntual (ARS 1.554)."}, {"accion": "agregar", "tipo": "negativa", "texto": "204", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gri 204» (ARS 2.036)."}, {"accion": "agregar", "tipo": "negativa", "texto": "404", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gri 404 1» (ARS 2.171), «gri 404» (ARS 448)."}, {"accion": "agregar", "tipo": "negativa", "texto": "402", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gri 402» (ARS 881)."}, {"accion": "agregar", "tipo": "negativa", "texto": "403", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gri 403» (ARS 671)."}, {"accion": "agregar", "tipo": "negativa", "texto": "300", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gri 300» (ARS 334)."}, {"accion": "agregar", "tipo": "negativa", "texto": "13", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«gri 13» (ARS 1.283)."}, {"accion": "agregar", "tipo": "negativa", "texto": "ejemplos", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«matriz de materialidad ejemplos» (ARS 2.525): la negativa actual es «ejemplo», en singular, y no cubre el plural."}]}, {"accion": "anuncio", "titulo": "Cambiar 3 títulos y 2 descripciones", "donde": "PS Argentina - SuSe - ESG / Reportes - Search › grupo «Reportes ESG» · anuncio id 817970221367", "detalle": "Tiene 14 títulos de 15 y las 4 descripciones: cada propuesta reemplaza a una.", "items": [{"accion": "reemplazar", "tipo": "titulo", "texto": "CSRD y Doble Materialidad", "destino": "Anuncio id 817970221367 · grupo «Reportes ESG»", "reemplaza": "Datos ESG", "prioritario": true, "motivo": "«csrd» es la búsqueda con más impresiones (76) y el anuncio no la nombra."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Reportes con Estándares GRI", "destino": "Anuncio id 817970221367 · grupo «Reportes ESG»", "reemplaza": "Impacto ESG", "prioritario": true, "motivo": "«estándares gri» (31 impresiones) y «reportes gri»: dicho como servicio."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Co-desarrollamos tu reporte de sostenibilidad: estándares GRI, indicadores y materialidad.", "destino": "Anuncio id 817970221367 · grupo «Reportes ESG»", "reemplaza": "Defina estrategia ESG, reportes y materialidad con soporte experto.", "prioritario": true, "motivo": "Voz de Peterson («co-desarrollamos») y las tres cosas que se buscan."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Doble materialidad y CSRD con una hoja de ruta clara. Te acompañamos en todo el proceso.", "destino": "Anuncio id 817970221367 · grupo «Reportes ESG»", "reemplaza": "Ordene datos, indicadores y prioridades para sostenibilidad corporativa.", "prioritario": true, "motivo": "Nombra CSRD, la búsqueda más frecuente, en el texto largo."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Indicadores GRI: Te Guiamos", "destino": "Anuncio id 817970221367 · grupo «Reportes ESG»", "reemplaza": "Plan ESG Empresa", "opcional": true, "motivo": "«indicadores gri»: 2 clics. Peterson acompaña."}]}], "anuncios": [{"grupo": "Reportes ESG", "anuncio_id": "817970221367", "anuncio_desc": "fuerza Buena, 67 clics y ARS 100.676 del 1 sep – 20 oct 2026", "url": "https://americas.peterson-solutions.com/service/estrategia-y-gestion-de-sostenibilidad/", "gasto_ars": 100676, "clics": 67, "ventanas": "1 sep – 20 oct 2026", "titulos_hoy": ["Consultoria ESG", "Estrategia ESG", "Reportes ESG", "Reporte GRI", "Reporte CSRD", "Materialidad ESG", "Datos ESG", "Finanzas Sostenibles", "Gestion Sostenible", "Consultoria Peterson", "Plan ESG Empresa", "Reporte Sostenibilidad", "Impacto ESG", "Agenda Una Reunion"], "descripciones_hoy": ["Defina estrategia ESG, reportes y materialidad con soporte experto.", "Ordene datos, indicadores y prioridades para sostenibilidad corporativa.", "Prepare reportes GRI, CSRD o internos con una hoja de ruta clara.", "Hable con Peterson para transformar objetivos ESG en acciones."], "accion": "Ajustar", "motivo": "Es el anuncio que mejor anda (fuerza Buena, 67 clics). No nombra «estándares GRI», «indicadores» ni «doble materialidad», que es como busca quien tiene que reportar. Dos descripciones están en «usted» genérico («Defina…», «Ordene…»): la voz de Peterson es «nosotros» y el protagonista es el cliente.", "quitar": [{"texto": "Datos ESG", "motivo": "Genérico."}, {"texto": "Impacto ESG", "motivo": "Genérico."}, {"texto": "Plan ESG Empresa", "motivo": "Genérico y mal escrito."}, {"texto": "Defina estrategia ESG, reportes y materialidad con soporte experto.", "motivo": "El cliente hace todo y nosotros solo damos «soporte»: no es la voz de Peterson."}, {"texto": "Ordene datos, indicadores y prioridades para sostenibilidad corporativa.", "motivo": "Genérico."}], "titulos_propuestos": [{"texto": "CSRD y Doble Materialidad", "motivo": "«csrd» es la búsqueda con más impresiones (76) y el anuncio no la nombra.", "prioritario": true, "reemplaza": "Datos ESG"}, {"texto": "Reportes con Estándares GRI", "motivo": "«estándares gri» (31 impresiones) y «reportes gri»: dicho como servicio.", "prioritario": true, "reemplaza": "Impacto ESG"}, {"texto": "Indicadores GRI: Te Guiamos", "motivo": "«indicadores gri»: 2 clics. Peterson acompaña.", "reemplaza": "Plan ESG Empresa"}], "descripciones_propuestas": [{"texto": "Co-desarrollamos tu reporte de sostenibilidad: estándares GRI, indicadores y materialidad.", "motivo": "Voz de Peterson («co-desarrollamos») y las tres cosas que se buscan.", "prioritario": true, "reemplaza": "Defina estrategia ESG, reportes y materialidad con soporte experto."}, {"texto": "Doble materialidad y CSRD con una hoja de ruta clara. Te acompañamos en todo el proceso.", "motivo": "Nombra CSRD, la búsqueda más frecuente, en el texto largo.", "prioritario": true, "reemplaza": "Ordene datos, indicadores y prioridades para sostenibilidad corporativa."}], "terminos": [{"termino": "csrd", "relacion": "fuerte", "coste": 5046, "clics": 2}, {"termino": "indicadores gri", "relacion": "parcial", "coste": 4173, "clics": 2}, {"termino": "standard gri", "relacion": "fuerte", "coste": 3086, "clics": 1}, {"termino": "estandar gri", "relacion": "fuerte", "coste": 2812, "clics": 1}, {"termino": "gri sustentabilidad", "relacion": "fuerte", "coste": 2718, "clics": 1}, {"termino": "estándares gri en español", "relacion": "parcial", "coste": 2477, "clics": 1}, {"termino": "gri l", "relacion": "nula", "coste": 2468, "clics": 1}, {"termino": "informes gri", "relacion": "fuerte", "coste": 2315, "clics": 1}], "nota": "El grupo «Materialidad» (anuncio id 817970221361) tiene el mismo texto: «Matriz de Materialidad» iría mejor ahí."}], "organico": [], "organico_desde": "Argentina", "organico_hasta": "14 sep 2026", "datos_hasta": "21 oct 2026", "unifica": ["PS:SEM:anuncio:ps-argentina-suse-esg-reportes:reportes-esg", "PS:SEM:plan:argentina:esg-la-mas-sana-con-los-mismos-huecos"], "keywords": [], "negativas": [{"texto": "201", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gri 201»: indicador puntual (ARS 1.554)."}, {"texto": "204", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gri 204» (ARS 2.036)."}, {"texto": "404", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gri 404 1» (ARS 2.171), «gri 404» (ARS 448)."}, {"texto": "402", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gri 402» (ARS 881)."}, {"texto": "403", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gri 403» (ARS 671)."}, {"texto": "300", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gri 300» (ARS 334)."}, {"texto": "13", "concordancia": "amplia", "nivel": "campaña", "motivo": "«gri 13» (ARS 1.283)."}, {"texto": "ejemplos", "concordancia": "amplia", "nivel": "campaña", "motivo": "«matriz de materialidad ejemplos» (ARS 2.525): la negativa actual es «ejemplo», en singular, y no cubre el plural."}], "negativas_decision": "Sí: 8 negativas, solo los números que tuvieron clic. No se pueden negativizar los 70 de una vez (Google no acepta patrones); los demás tuvieron impresiones sin clic. Revisar el mes que viene. No se suman exactas de «csrd» ni «estándares gri» sueltas: ya entran por «reporte CSRD» y «reporte GRI», y solas son mayormente lectura.", "revisiones": [{"mes": "2026-10", "accion": "unificación", "datos_hasta": "21 oct 2026"}]}'::jsonb, campana_id = c.id, grupo_id = g.id, actualizada_por = 'Unificación de 