update seo_sem.recomendaciones r set titulo = 'PS Argentina - Huella de agua: pausar «gestion del agua industrial» (97% del gasto, todo tratamiento de efluentes) · anuncio sin textos internos', detalle = 'La frase «gestion del agua industrial» se llevó ARS 95.754 de ARS 99.102 (97%) en búsquedas de tratamiento de efluentes, un servicio que Peterson no da. Pausarla y sumar negativas. Además, los anuncios de la campaña publican dos notas internas como descripciones («Testee demanda en sectores…», «…definir alcance y viabilidad del servicio»): cambiarlas ya.', prioridad = 'media', evidencia = '{"ficha": "campana", "unidad": "Argentina", "campana": "PS Argentina - SuSe - Huella de agua - Search", "acciones": ["pausa", "negativas", "anuncio"], "resumen": "Dejar de pagar tratamiento de efluentes y sacar las notas internas de los anuncios.", "por_que": "1 sep – 20 oct 2026: 37 clics y ARS 99.102, sin conversiones. «gestion del agua industrial» (frase) se llevó 32 clics y ARS 95.754 (97%), todos en tratamiento de agua y efluentes: «tratamiento de efluentes industriales argentina», «tratamiento de aguas industriales», «planta de tratamiento de efluentes industriales». El grupo «Huella hidrica», que es el servicio, gastó ARS 3.348; ahí entran calculadoras («calculadora huella hidrica», «fundacion aquae calculadora huella hidrica»).", "ya_hecho": "Nada de lo propuesto en septiembre: la keyword sigue activa y la campaña no tiene negativas propias.", "pasos": [{"accion": "pausa", "titulo": "Pausar la keyword «gestion del agua industrial»", "donde": "PS Argentina - SuSe - Huella de agua - Search › grupo «Gestion agua» · keyword en frase", "detalle": "El grupo queda con 5 keywords de eficiencia y medición, que no tuvieron clics.", "items": [{"accion": "pausar", "tipo": "keyword", "texto": "gestion del agua industrial", "concordancia": "frase", "destino": "Grupo «Gestion agua»", "motivo": "32 clics y ARS 95.754 (97% de la campaña), todos en tratamiento de efluentes."}]}, {"accion": "negativas", "titulo": "Sumar 5 negativas de campaña", "donde": "PS Argentina - SuSe - Huella de agua - Search › toda la campaña", "items": [{"accion": "agregar", "tipo": "negativa", "texto": "tratamiento", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«tratamiento de efluentes industriales argentina» (ARS 4.006), «tratamiento de aguas industriales» (ARS 3.096)."}, {"accion": "agregar", "tipo": "negativa", "texto": "efluentes", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "El mismo servicio, dicho de otra forma."}, {"accion": "agregar", "tipo": "negativa", "texto": "residuales", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«tratamiento de aguas residuales en la industria papelera»."}, {"accion": "agregar", "tipo": "negativa", "texto": "planta", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«planta de tratamiento de efluentes industriales»."}, {"accion": "agregar", "tipo": "negativa", "texto": "calculadora", "concordancia": "amplia", "destino": "Toda la campaña", "motivo": "«calculadora huella hidrica» y variantes: 6 clics. Buscan una herramienta gratis; la negativa actual es «calculadora gratis»."}]}, {"accion": "anuncio", "titulo": "Cambiar 4 títulos y las 2 descripciones internas", "donde": "PS Argentina - SuSe - Huella de agua - Search › grupo «Huella hidrica» · anuncio id 817970221139", "detalle": "Hacer lo mismo con las dos descripciones en los anuncios de «Gestion agua» (id 817970221142) y «Riesgo hidrico» (id 817970221145), que tienen el mismo texto.", "items": [{"accion": "reemplazar", "tipo": "titulo", "texto": "Huella Hídrica Corporativa", "destino": "Anuncio id 817970221139 · grupo «Huella hidrica»", "reemplaza": "Gestion Del Agua", "prioritario": true, "motivo": "Lo que Peterson mide, con la palabra que la diferencia del tratamiento de agua."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Medimos Tu Huella Hídrica", "destino": "Anuncio id 817970221139 · grupo «Huella hidrica»", "reemplaza": "Agua En Industria", "prioritario": true, "motivo": "Voz de Peterson y protagonista el cliente."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Te acompañamos a medir la huella hídrica de tu empresa y de tu producto.", "destino": "Anuncio id 817970221139 · grupo «Huella hidrica»", "reemplaza": "Testee demanda en sectores con alto consumo de agua y presion ESG.", "prioritario": true, "motivo": "Reemplaza la nota interna con lo que hace Peterson."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Hablemos de tu consumo de agua: te decimos por dónde empezar a medir.", "destino": "Anuncio id 817970221139 · grupo «Huella hidrica»", "reemplaza": "Hable con Peterson para definir alcance y viabilidad del servicio.", "prioritario": true, "motivo": "Cierre con un pedido concreto, sin hablar de «viabilidad»."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Riesgo Hídrico en Tu Cadena", "destino": "Anuncio id 817970221139 · grupo «Huella hidrica»", "reemplaza": "Consumo De Agua", "opcional": true, "motivo": "El otro servicio de la campaña."}, {"accion": "reemplazar", "tipo": "titulo", "texto": "Huella de Agua ISO 14046", "destino": "Anuncio id 817970221139 · grupo «Huella hidrica»", "reemplaza": "Agua Agroindustrial", "opcional": true, "motivo": "Nombra la norma de huella hídrica. Confirmar que el servicio la usa antes de publicarlo."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Te acompañamos a medir la huella hídrica de tu empresa y de tu producto.", "reemplaza": "Testee demanda en sectores con alto consumo de agua y presion ESG.", "destino": "Anuncio id 817970221142 · grupo «Gestion agua»", "prioritario": true, "motivo": "Mismo texto interno que en «Huella hidrica»."}, {"accion": "reemplazar", "tipo": "descripcion", "texto": "Hablemos de tu consumo de agua: te decimos por dónde empezar a medir.", "reemplaza": "Hable con Peterson para definir alcance y viabilidad del servicio.", "destino": "Anuncio id 